func TestGettersWalletTransactionAmount(t *testing.T) {
	t.Run("GetIsoCurrencyCode", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &WalletTransactionAmount{}
		var expected WalletIsoCurrencyCode
		obj.IsoCurrencyCode = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetIsoCurrencyCode(), "getter should return the property value")
	})

	t.Run("GetIsoCurrencyCode_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *WalletTransactionAmount
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetIsoCurrencyCode() // Should return zero value
	})

	t.Run("GetValue", func(t *testing.T) {
		t.Parallel()
		// Arrange
		obj := &WalletTransactionAmount{}
		var expected float64
		obj.Value = expected

		// Act & Assert
		assert.Equal(t, expected, obj.GetValue(), "getter should return the property value")
	})

	t.Run("GetValue_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *WalletTransactionAmount
		// Should not panic - getters should handle nil receiver gracefully
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("Getter panicked on nil receiver: %v", r)
			}
		}()
		_ = obj.GetValue() // Should return zero value
	})

}

